import{_ as a,c as i,o as t,a2 as r}from"./chunks/framework.bjzS3PU6.js";const u=JSON.parse('{"title":"Hill Devil State Park","description":"","frontmatter":{},"headers":[],"relativePath":"entries/locations/Hill-Devil-State-Park.md","filePath":"entries/locations/Hill-Devil-State-Park.md"}'),n={name:"entries/locations/Hill-Devil-State-Park.md"};function o(s,e,l,c,h,d){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="hill-devil-state-park" tabindex="-1">Hill Devil State Park <a class="header-anchor" href="#hill-devil-state-park" aria-label="Permalink to &quot;Hill Devil State Park&quot;">​</a></h1><hr><p><strong>LOCATION TYPE</strong>: State Park<br><strong>LOCATION</strong>: Near <a href="./Saint-Juniper">Saint Juniper</a><br><strong>ESTABLISHED</strong>: Mid-20th century (public park)<br><strong>FEATURES</strong>: Pine forest, hiking trails<br><strong>STATUS</strong>: Active (public recreation area); contains restricted facilities</p><hr><p><strong>Hill Devil State Park</strong> is a public recreational area located near <a href="./Saint-Juniper">Saint Juniper</a>, featuring a sprawling forest of pine trees and maintained hiking trails. The park became the center of controversy following an October 1995 incident in which <a href="./../people/Kai-Shepherd">Kai Shepherd</a>, a local resident, disappeared under unexplained circumstances near a restricted facility within the park boundaries. The incident prompted investigation by activist organization <a href="./../organizations/The-Bloc">The Bloc</a> and brought attention to alleged <a href="./../organizations/Miter-Corporation">Miter Corporation</a> operations in the area.</p><p><strong>At a glance</strong></p><ul><li>Public state park serving Saint Juniper residents with pine forest and hiking trails</li><li>Site of <a href="./../people/Kai-Shepherd">Kai Shepherd</a> disappearance (October 1995)</li><li>Contains restricted property marked &quot;SJ SECURELAB&quot; belonging to <a href="./../organizations/Miter-Corporation">Miter Corporation</a></li><li>Location of alleged covert research facility (<a href="./Saint-Juniper-Research-Campus">Saint Juniper Research Campus</a>)</li><li>Incident led to formation of <a href="./../organizations/The-Bloc">The Bloc</a> activist organization (1999)</li><li>Continues to operate as public recreation area while containing restricted zones</li></ul><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Hill Devil State Park serves as a recreational area for residents of nearby Saint Juniper, offering hiking trails through dense pine forests. The park&#39;s natural beauty and well-maintained trails made it a popular destination for weekend outings and exercise. However, the park&#39;s reputation changed dramatically following events in October 1995 that brought attention to the presence of restricted facilities within its boundaries.</p><p>According to documentation recovered by <a href="./../organizations/The-Bloc">The Bloc</a>, portions of the park contain property operated by the <a href="./../organizations/Miter-Corporation">Miter Corporation</a>, marked with security fencing and &quot;DO NOT ENTER&quot; signage identifying the area as &quot;SJ SECURELAB.&quot; These restricted areas allegedly house the <a href="./Saint-Juniper-Research-Campus">Saint Juniper Research Campus</a>, a covert research facility that became the subject of activist investigation.</p><h2 id="geography-and-features" tabindex="-1">Geography and features <a class="header-anchor" href="#geography-and-features" aria-label="Permalink to &quot;Geography and features&quot;">​</a></h2><p>The park consists primarily of pine forest with maintained hiking trails accessible to the public. The terrain includes both well-traveled paths and more remote areas deeper within the forest. Natural features include:</p><ul><li>Dense pine forest with mature trees</li><li>Maintained recreational trails</li><li>Forest floor covered with pine needles and natural debris</li><li>Remote areas suitable for extended hiking</li></ul><p>The park&#39;s forested areas provide screening between public recreational zones and restricted facilities, making it difficult for casual visitors to observe secured areas from public trails.</p><h2 id="the-october-1995-incident" tabindex="-1">The October 1995 incident <a class="header-anchor" href="#the-october-1995-incident" aria-label="Permalink to &quot;The October 1995 incident&quot;">​</a></h2><h3 id="the-disappearance" tabindex="-1">The disappearance <a class="header-anchor" href="#the-disappearance" aria-label="Permalink to &quot;The disappearance&quot;">​</a></h3><p>On a weekend in October 1995, four young people from Saint Juniper went hiking at Hill Devil State Park, accompanied by a pet pug named Pubes. The group followed a maintained trail through the forest. As sunset approached, they encountered a security fence with &quot;DO NOT ENTER&quot; signage identifying the restricted area as &quot;SJ SECURELAB&quot; property.</p><p>According to eyewitness testimony from the three surviving members of the group, they heard a strange buzzing sound at this location. Looking up, they observed an unidentified aerial craft described as triangular in shape. The craft emitted a bright light directed at the group. Witnesses stated that <a href="./../people/Kai-Shepherd">Kai Shepherd</a>, one of the four hikers, was &quot;pulled up effortlessly&quot; into the craft and subsequently disappeared.</p><h3 id="community-impact" tabindex="-1">Community impact <a class="header-anchor" href="#community-impact" aria-label="Permalink to &quot;Community impact&quot;">​</a></h3><p>The incident devastated the local Saint Juniper community, affecting the families of those involved and creating lasting trauma for the witnesses. One witness, later known by the alias <a href="./../people/Z-L1NE">Z*L1NE</a>, became obsessed with understanding what had occurred and spent extensive time researching paranormal phenomena at the <a href="./St-Juniper-Paranormal-Museum">St. Juniper Paranormal Museum</a>.</p><p>The disappearance received attention from local authorities, though no official findings were made public. The case remains unresolved.</p><h2 id="restricted-facilities" tabindex="-1">Restricted facilities <a class="header-anchor" href="#restricted-facilities" aria-label="Permalink to &quot;Restricted facilities&quot;">​</a></h2><h3 id="sj-securelab" tabindex="-1">SJ SECURELAB <a class="header-anchor" href="#sj-securelab" aria-label="Permalink to &quot;SJ SECURELAB&quot;">​</a></h3><p>Within the park boundaries lies property marked with security fencing and signage identifying it as &quot;SJ SECURELAB.&quot; According to materials recovered by <a href="./../organizations/The-Bloc">The Bloc</a>, this property is operated by the <a href="./../organizations/Miter-Corporation">Miter Corporation</a> and houses what activists allege to be a covert research facility known as the <a href="./Saint-Juniper-Research-Campus">Saint Juniper Research Campus</a>.</p><p>The restricted area is enclosed by chain-link fencing with warning signs prohibiting entry. The facility is located in a remote section of the park&#39;s forested area, screened from public trails by dense tree cover. According to The Bloc&#39;s allegations, the facility conducts research programs involving human subjects, though these claims have not been independently verified.</p><h3 id="discovery-and-investigation" tabindex="-1">Discovery and investigation <a class="header-anchor" href="#discovery-and-investigation" aria-label="Permalink to &quot;Discovery and investigation&quot;">​</a></h3><p>The presence of the restricted facility came to wider attention following the October 1995 incident. <a href="./../people/Z-L1NE">Z*L1NE</a>, one of the witnesses to Kai Shepherd&#39;s disappearance, subsequently met computer security researchers <a href="./../people/1NK">1NK</a> and <a href="./../people/GUMM1">GUMM1</a> who claimed to have accessed secure portals for the Miter Corporation. Their investigation revealed documentation suggesting the company operated a laboratory in the woods at Hill Devil State Park where, according to their findings, subjects were being used in experimental programs.</p><p>These discoveries led to the formation of <a href="./../organizations/The-Bloc">The Bloc</a> in 1999, with Hill Devil State Park remaining a focus of their investigative efforts.</p><h2 id="current-status" tabindex="-1">Current status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current status&quot;">​</a></h2><p>Hill Devil State Park continues to operate as a public recreational area, with trails and forest access available to Saint Juniper residents. The restricted facility within park boundaries remains secured with fencing and warning signage. Neither Miter Corporation nor local authorities have issued public statements regarding the facility&#39;s operational status or the nature of activities conducted there.</p><p>The park remains associated with the October 1995 incident in local memory, though it continues to serve its function as a recreational area for the community.</p><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./../people/Kai-Shepherd">Kai Shepherd</a> — Disappeared at the park in October 1995</li><li><a href="./Saint-Juniper-Research-Campus">Saint Juniper Research Campus</a> — Alleged facility within park boundaries</li><li><a href="./../organizations/The-Bloc">The Bloc</a> — Activist organization investigating the park and facility</li><li><a href="./../people/Z-L1NE">Z*L1NE</a> — Witness to the October 1995 incident; co-founder of The Bloc</li><li><a href="./../people/1NK">1NK</a> — The Bloc co-founder who investigated facility</li><li><a href="./../people/GUMM1">GUMM1</a> — The Bloc co-founder who investigated facility</li><li><a href="./../organizations/Miter-Corporation">Miter Corporation</a> — Alleged operator of restricted facility</li><li><a href="./Saint-Juniper">Saint Juniper</a> — Nearby town</li><li><a href="./St-Juniper-Paranormal-Museum">St. Juniper Paranormal Museum</a> — Location where witnesses researched the incident</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li><strong>Eyewitness testimony from October 1995 incident</strong> — Documented by researchers and activists investigating disappearances at Hill Devil State Park</li><li><strong>Visual documentation recovered by The Bloc</strong> — Shows security fencing and &quot;SJ SECURELAB&quot; signage within park boundaries</li><li><strong>Internal network documentation</strong> — Files recovered from sj-securelab.net by activist researchers, indicating facility operations within Hill Devil State Park</li><li><strong>Regional documentation</strong> — Materials concerning unexplained disappearances near Saint Juniper (mid-1990s)</li></ol><hr><p><em>This article is part of the Saint Juniper Research Documentation Project</em></p>',37)])])}const f=a(n,[["render",o]]);export{u as __pageData,f as default};
